/* HRM › Recruitment › Dashboard (R0). Headline counts come from live data; trend charts are illustrative. */
(function () {
  const { S, esc, acts, chs } = App; const H = App.H;
  let range = 'Last 90 days';
  H.route('/hrm/dashboard', () => {
    const open = S.recruitments.filter(r => r.status !== 'Draft');
    const vac = open.reduce((a, r) => a + Math.max(0, r.vacancies - r.hired), 0);
    const all = S.candidates.length, hired = S.candidates.filter(c => c.status === 'hired').length + 7;
    const pool = S.candidates.filter(c => c.pools.length).length + 32;
    const total = all + 117;
    const counts = st => S.candidates.filter(c => c.status === 'progress' && c.stage === st).length;
    const funnel = [['Applied', 142], ['Screening', 88], ['Interview', 46], ['Technical test', 21], ['Offer', 12], ['Hired', 9]];
    const up = S.interviews.filter(i => i.status !== 'Completed' && i.day >= H.today).sort((a, b) => (a.day + a.time).localeCompare(b.day + b.time)).slice(0, 5);
    const byStage = [['Unassigned', counts('unassigned') + 3], ...S.stages.map(s => [s.name.replace('Technical test', 'Tech test'), counts(s.id) * 3 + (s.id === 'hired' ? 7 : 4)])];
    const bmax = Math.max(...byStage.map(b => b[1]));
    const status = [['In progress', 98, '#2C7A7B'], ['Talent pool', 21, '#9C27B0'], ['Cancelled', 14, '#D32F2F'], ['Hired', 9, '#2E7D32']];
    const source = [['Career page', 65, '#2C7A7B'], ['LinkedIn', 31, '#0288D1'], ['Referral', 20, '#9C27B0'], ['Indeed', 16, '#EF6C00'], ['Agency', 10, '#E0E0E0']];
    const donut = (rows, label) => { let acc = 0; const sum = rows.reduce((a, r) => a + r[1], 0); const stops = rows.map(r => { const a = acc; acc += r[1] / sum * 100; return `${r[2]} ${a}% ${acc}%`; }).join(','); return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops})" role="img" aria-label="${label}"><span><small>Total</small><b>${sum}</b></span></div><ul class="legend-list">${rows.map(r => `<li><i style="background:${r[2]}"></i>${r[0]}<b>${r[1]}</b><span>${Math.round(r[1] / sum * 100)}%</span></li>`).join('')}</ul></div>`; };
    const pipeRows = open.filter(r => r.status !== 'Draft').map(r => { const cs = S.candidates.filter(c => c.rid === r.id && c.status === 'progress'); const n = id => cs.filter(c => c.stage === id).length; return [r, n('unassigned'), n('applied'), n('screening'), n('interview'), n('test'), n('offer'), cs.length]; });
    const tot = i => pipeRows.reduce((a, r) => a + r[i], 0);
    const months = [['May', 34], ['Jun', 31], ['Jul', 29], ['Aug', 28], ['Sep', 26], ['Oct', 24]];
    const joins = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].map((m, i) => [m, [0, 0, 1, 0, 1, 1, 0, 2, 2, 2, 0, 0][i]]);
    return H.frame({ tab: 'dashboard', primary: `<button class="btn primary lg" data-act="rec-new"><i class="ri-add-circle-line"></i>New recruitment</button>`, title: 'Dashboard', sub: 'Hiring at QA Riverside Private Clinic — vacancies, pipeline health and upcoming interviews at a glance.',
      actions: `<div class="field select sm pillsel">${`<select data-ch="dash-range" aria-label="Date range">${['Last 30 days', 'Last 90 days', 'This year'].map(o => `<option ${o === range ? 'selected' : ''}>${o}</option>`).join('')}</select>`}</div><button class="btn outlined" data-act="dash-export"><i class="ri-download-2-line"></i>Export</button>`,
      body: `<div class="hbody stack g16">
      <div class="stats five">${[['Total vacancies', vac, 'Open positions', 'ri-briefcase-4-line', 'feature', '#/hrm/recruitments'], ['Ongoing', open.filter(r => r.status !== 'Completed').length, 'Active recruitments', 'ri-team-line', '', '#/hrm/recruitments'], ['Hired', hired, `of ${total} candidates`, 'ri-user-follow-line', '', '#/hrm/candidates'], ['Conversion rate', (hired / total * 100).toFixed(1) + '%', 'Hired / total candidates', 'ri-line-chart-line', '', ''], ['Talent pool', pool, 'Candidates in pool', 'ri-heart-3-line', '', '#/hrm/talent-pool']].map(([k, v, f, i, c, go]) => `<${go ? `a href="${go}"` : 'div'} class="stat ${c} kpi"><span class="row g8"><span class="ic"><i class="${i}"></i></span><span class="body2" style="font-weight:500">${k}</span></span><span class="num tnum">${v}</span><span class="foot">${f}</span></${go ? 'a' : 'div'}>`).join('')}</div>
      <div class="dgrid wide-left"><section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Stage conversion funnel</h2><p class="caption" style="margin:0">Share of total candidates reaching each stage</p></div>
          <div class="stack g12">${funnel.map(([k, v], i) => `<div class="hbar"><span>${k}</span><span class="track"><span style="width:${v / 142 * 100}%;background:rgba(44,122,123,${1 - i * .14})"></span></span><b class="tnum">${v}</b><small>${Math.round(v / 142 * 100)}%</small></div>`).join('')}</div></section>
        <section class="card card-pad stack g12"><div class="row between"><div><h2 class="sub2 h-card">Interviews</h2><p class="caption" style="margin:0">Upcoming scheduled interviews</p></div><a href="#/hrm/interviews" class="link">View all</a></div>
          ${up.map(i => { const c = H.cand(i.cid); return `<a class="up-row" href="#/hrm/candidates/${c.id}"><span class="person">${H.cav(c, 'lg')}<span class="cell2"><span>${esc(H.name(c))}</span><small>${esc(H.rec(c.rid).title)}</small></span></span><span class="cell2 right"><span class="${i.day === H.today ? 'brand' : ''}">${H.when(i)}</span><small><span class="chip sm filled ${{ Video: 't-blue', 'In person': 't-purple', Phone: 't-grey' }[i.mode]}">${i.mode}</span></small></span></a>`; }).join('')}</section></div>
      <div class="dgrid"><section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Candidates by stage</h2><p class="caption" style="margin:0">All active recruitments · where candidates are right now</p></div>
          <div class="vbars">${byStage.map(([k, v], i) => `<div class="vb"><small>${v}</small><span style="height:${v / bmax * 100}%;background:${i === 0 ? '#E0E0E0' : k === 'Hired' ? '#2E7D32' : '#2C7A7B'}"></span><small class="lab">${k}</small></div>`).join('')}</div></section>
        <section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Candidate status</h2><p class="caption" style="margin:0">All candidates</p></div>${donut(status, 'Candidate status')}</section></div>
      <div class="dgrid"><section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Source of hire</h2><p class="caption" style="margin:0">Where candidates come from</p></div>${donut(source, 'Source of hire')}</section>
        <section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Open positions by recruitment</h2><p class="caption" style="margin:0">Filled vs open vacancies</p></div><div class="legend"><span><i style="background:#2E7D32"></i>Filled</span><span><i style="background:#FF5722"></i>Open</span></div>
          <div class="stack g12">${open.filter(r => r.status !== 'Draft').map(r => `<div class="fo-row"><span>${esc(r.title)}</span><span class="fo"><span style="flex:${r.hired};background:#2E7D32"></span><span style="flex:${Math.max(0, r.vacancies - r.hired)};background:#FF5722"></span></span><small>${r.hired} filled · ${Math.max(0, r.vacancies - r.hired)} open</small></div>`).join('')}</div></section></div>
      <section class="card"><div class="card-head"><div><h2 class="sub2 h-card">Hiring pipeline</h2><p class="caption" style="margin:0">Candidates per stage per recruitment · in progress only</p></div></div>
        <div class="table-scroll"><table class="dt num-table"><thead><tr><th>Recruitment</th><th>Unassigned</th><th>Applied</th><th>Screening</th><th>Interview</th><th>Tech test</th><th>Offer</th><th>Total</th></tr></thead><tbody>${pipeRows.map(r => `<tr class="click" data-act="dash-pipe" data-id="${r[0].id}"><td><b style="font-weight:500">${esc(r[0].title)}</b></td>${r.slice(1, 7).map(n => `<td class="tnum">${n}</td>`).join('')}<td class="tnum brand"><b>${r[7]}</b></td></tr>`).join('')}<tr class="total"><td><b>Total</b></td>${[1, 2, 3, 4, 5, 6].map(i => `<td class="tnum">${tot(i)}</td>`).join('')}<td class="tnum brand"><b>${tot(7)}</b></td></tr></tbody></table></div></section>
      <div class="dgrid"><section class="card card-pad stack g16"><div><h2 class="sub2 h-card">Hire rate by recruitment</h2><p class="caption" style="margin:0">Conversion efficiency · hired ÷ candidates</p></div>
          <div class="stack g12">${open.map(r => { const n = S.candidates.filter(c => c.rid === r.id).length; const h = S.candidates.filter(c => c.rid === r.id && c.status === 'hired').length; const p = n ? h / n * 100 : 0; return `<div class="hbar"><span>${esc(r.title)}</span><span class="track"><span style="width:${p}%"></span></span><b class="tnum">${p.toFixed(1)}%</b><small>${h}/${n}</small></div>`; }).join('')}</div></section>
        <section class="card card-pad stack g16"><div class="row between"><div><h2 class="sub2 h-card">Time to hire</h2><p class="caption" style="margin:0">Average days from application to hire</p></div>${App.chip('▼ 4 days', 't-green', 'sm filled')}</div><div class="row g8" style="align-items:baseline"><b style="font-size:34px;font-weight:500">24</b><span class="caption">days on average</span></div>
          <div class="vbars short">${months.map(([m, v], i) => `<div class="vb"><small>${v}</small><span style="height:${v / 34 * 100}%;background:${i === 5 ? '#2C7A7B' : '#D3E5E5'}"></span><small class="lab">${m}</small></div>`).join('')}</div></section></div>
      <section class="card card-pad stack g16"><div class="row between"><div><h2 class="sub2 h-card">Joinings per month</h2><p class="caption" style="margin:0">Hired candidates by start month · 2026</p></div><span class="link">9 joined this year</span></div>
        <div class="vbars short">${joins.map(([m, v]) => `<div class="vb"><small>${v || ''}</small><span style="height:${v ? v / 2 * 100 : 3}%;background:${v ? '#2C7A7B' : '#EEE'}"></span><small class="lab">${m}</small></div>`).join('')}</div></section>
      <section class="card"><div class="card-head"><div><h2 class="sub2 h-card">Ongoing recruitments &amp; managers</h2><p class="caption" style="margin:0">Active hiring with assigned managers</p></div></div>
        <div class="table-scroll"><table class="dt"><thead><tr><th>Recruitment</th><th>Vacancy</th><th>Candidates</th><th>Managers</th><th>Closes</th></tr></thead><tbody>${open.map(r => `<tr class="click" data-act="dash-pipe" data-id="${r.id}"><td><b style="font-weight:500">${esc(r.title)}</b></td><td>${r.vacancies - r.hired} of ${r.vacancies} open</td><td class="tnum">${S.candidates.filter(c => c.rid === r.id).length}</td><td>${H.avs(r.managers)}</td><td>${esc(r.end)}</td></tr>`).join('')}</tbody></table></div></section>
      <section class="card card-pad stack g16"><div class="row between"><div><h2 class="sub2 h-card">Source conversion rate</h2><p class="caption" style="margin:0">Hire rate per candidate source</p></div><div class="legend"><span><i style="background:#2E7D32"></i>Hired</span><span><i style="background:#E0E0E0"></i>Total</span></div></div>
        <div class="src-bars">${[['Career page', 3, 65], ['LinkedIn', 1, 31], ['Referral', 4, 20], ['Indeed', 0, 16], ['Agency', 1, 10]].map(([k, h, t]) => `<div><div class="pair"><span style="height:${h / 65 * 100}%;background:#2E7D32" title="${h} hired"></span><span style="height:${t / 65 * 100}%;background:#E0E0E0" title="${t} total"></span></div><small>${k}</small><small class="${h / t > .1 ? 'good' : ''}">${(h / t * 100).toFixed(1)}% hired</small></div>`).join('')}</div></section>
      </div>` });
  });
  chs['dash-range'] = el => { range = el.value; App.render(); App.snack(`Showing ${range.toLowerCase()}.`, 'info'); };
  acts['dash-export'] = () => App.snack('Recruitment report exported as PDF.', 'info');
  acts['dash-pipe'] = el => { App.ui.hrmRec = el.dataset.id; App.go('#/hrm/pipeline'); };
  acts['rec-new'] = () => H.openRecruitment(null);
})();
